import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    df['species'] = df['species'].str.strip().replace('Chinstarp', 'Chinstrap')
    df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    return df.groupby('island')['penguin_id'].count().to_dict()
